code_sketch:
abstract record Op;
sealed record Get(string Key) : Op;
sealed record Put(string Key, int Value) : Op;
sealed record Log(string Message) : Op;

static int Run(Op op, IStore store) => op switch
{
    Get g => store.Read(g.Key),
    Put p => store.Write(p.Key, p.Value),
    Log l => store.Log(l.Message),
    _ => throw new UnreachableException()
};

